def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    pts = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c]:
                pts.setdefault(grid[r][c], []).append((r, c))

    def put(r, c, v):
        if 0 <= r < h and 0 <= c < w:
            out[r][c] = v

    # Color 1 makes a short eastward trail and a raised endpoint.
    for r, c in pts.get(1, []):
        put(r, c + 1, 5)
        put(r, c + 2, 5)
        put(r - 1, c + 2, 1)

    # Color 2 makes a westward trail.
    rays2 = set()
    for r, c in pts.get(2, []):
        for d in range(1, 5):
            x = (r, c - d)
            if 0 <= x[1] < w:
                rays2.add(x)
                put(*x, 2 if d == 4 else 5)

    # Color 3 extends downward; color 6 extends upward.
    rays3, rays6 = set(), set()
    for r, c in pts.get(3, []):
        for d in range(1, 4):
            x = (r + d, c)
            if x[0] < h:
                rays3.add(x)
                put(*x, 3 if d == 3 else 5)
    for r, c in pts.get(6, []):
        for d in range(1, 7):
            x = (r - d, c)
            if x[0] >= 0:
                rays6.add(x)
                put(*x, 6 if d == 6 else 5)

    # A crossing of the 2 trail with a 3 or 6 trail becomes a 4,
    # followed by a diagonal trail down-left.
    for r, c in rays2 & (rays3 | rays6):
        put(r, c, 4)
        d = 1
        while r + d < h and c - d >= 0:
            put(r + d, c - d, 4)
            d += 1

    # Keep the original colored markers intact.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                out[r][c] = grid[r][c]
    return out
